// 简化版原理
public class MapperProxy<T> implements InvocationHandler {
    private final SqlSession session; private final Class<T> mapperInterface;
    public Object invoke(Object proxy, Method m, Object[] args) {
        String statementId = mapperInterface.getName() + "." + m.getName();
        if (List.class.isAssignableFrom(m.getReturnType()))
            return session.selectList(statementId, args == null ? null : args[0]);
        return session.selectOne(statementId, args == null ? null : args[0]);
    }
}
