@MappedTypes(OrderStatus.class)
public class OrderStatusHandler extends BaseTypeHandler<OrderStatus> {
    public void setNonNullParameter(PreparedStatement ps, int i, OrderStatus s, JdbcType t)
            throws SQLException { ps.setInt(i, s.getCode()); }
    public OrderStatus getNullableResult(ResultSet rs, String col) throws SQLException {
        int code = rs.getInt(col);
        return rs.wasNull() ? null : OrderStatus.of(code);
    }
    public OrderStatus getNullableResult(ResultSet rs, int idx) throws SQLException {
        int code = rs.getInt(idx); return rs.wasNull() ? null : OrderStatus.of(code); }
    public OrderStatus getNullableResult(CallableStatement cs, int idx) throws SQLException {
        int code = cs.getInt(idx); return cs.wasNull() ? null : OrderStatus.of(code); }
}

