@Aspect @Component @Order(1)
public class LogAspect {
    @Around("@annotation(com.demo.Timed)")
    public Object time(ProceedingJoinPoint pjp) throws Throwable {
        long start = System.nanoTime();
        try { return pjp.proceed(); }                  // 必须调用并返回
        finally { log.info("{} cost {}ms", pjp.getSignature(),
                           (System.nanoTime() - start) / 1_000_000); }
    }
    @AfterReturning(pointcut = "execution(* com.demo.order..*(..))", returning = "r")
    public void ok(Object r) { log.debug("result={}", r); }
    @AfterThrowing(pointcut = "execution(* com.demo.order..*(..))", throwing = "e")
    public void fail(Exception e) { alarm.send(e); }
}

